{
  "apiVersion": 1,
  "type": "help",
  "data": {
    "command": "astryx upgrade",
    "description": "Update your code after upgrading Astryx, and refresh ShadCN-copied components",
    "usage": "astryx upgrade [options]",
    "options": [
      {
        "flags": "--from <version>",
        "description": "Previous version before the dependency upgrade; required unless --list or --registry is set. The target is the installed @astryxdesign/core version, or legacy @xds/core when @astryxdesign/core is not installed"
      },
      {
        "flags": "--apply",
        "description": "Write changes to disk; without it, the run is a dry run",
        "defaultValue": false
      },
      {
        "flags": "--force",
        "description": "Run codemods even if --from is newer than the installed version",
        "defaultValue": false
      },
      {
        "flags": "--codemod <name>",
        "description": "Run only the named codemod. Optional codemods run only when named here; a normal run skips them. Also skips the check of ShadCN-copied compositions. An unknown name exits 1 with ERR_UNKNOWN_CODEMOD when the version range has codemods"
      },
      {
        "flags": "--skip-codemod <name...>",
        "description": "Exclude named codemods (repeatable). Re-run past a failed codemod by skipping it."
      },
      {
        "flags": "--integration <package>",
        "description": "Explicit integration specifier (repeatable). Resolved beneath node_modules; absolute paths and `.` or `..` segments are rejected.",
        "defaultValue": []
      },
      {
        "flags": "--path <dir>",
        "description": "Source directory to scan, relative to where you run the command, however you spell it. Without --path, the project's src folder, from any folder in the project",
        "defaultValue": "./src at the project root"
      },
      {
        "flags": "--install-deps",
        "description": "Install jscodeshift when it is missing. Without it, a missing jscodeshift fails the command with ERR_DEP_MISSING",
        "defaultValue": false
      },
      {
        "flags": "--registry",
        "description": "Only update ShadCN-copied compositions from their install receipts: unchanged files are updated, edits that do not overlap are merged, and conflicts are left untouched; --from is not required. Combining it with --list, --from, --force, --codemod, --skip-codemod, --integration or --install-deps exits 1 with ERR_INVALID_ARGUMENT",
        "defaultValue": false
      },
      {
        "flags": "--list",
        "description": "List available codemods and do nothing else. Every other flag is refused, as is --registry (exit 1)",
        "defaultValue": false
      }
    ],
    "subcommands": []
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
